{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP (Port 80) Access from Internet",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows ingress traffic on port 80 (HTTP) from any source (0.0.0.0/0). This exposes the service to unencrypted traffic, increasing the risk of man-in-the-middle attacks and data interception. Port 443 (HTTPS) is also open, which is standard for public web services, but port 80 should generally be restricted or used only for redirects."
    }
  ],
  "patched_code": "resource "google_compute_firewall" "allow_http" {
  name    = "digital-library-content-management-platform-firewall-http"
  network = google_compute_network.digital_library_vpc.name
  allow {
    protocol = "tcp"
    ports    = ["443"]
  }
  source_ranges = ["0.0.0.0/0"]
  target_tags   = ["http-server"]
}

resource "google_compute_firewall" "allow_http_redirect" {
  name    = "digital-library-content-management-platform-firewall-http-redirect"
  network = google_compute_network.digital_library_vpc.name
  allow {
    protocol = "tcp"
    ports    = ["80"]
  }
  source_ranges = ["0.0.0.0/0"]
  target_tags   = ["http-server"]
}",
  "fix_summary": "Split the original firewall rule into two separate resources. The first resource now only allows HTTPS (port 443) from the internet, enforcing encrypted communication. The second resource explicitly allows HTTP (port 80) from the internet, typically intended for redirecting users to HTTPS, thereby separating the concerns and making the security posture clearer while maintaining functionality if a load balancer or web server handles the redirect."
}
